"""Claude on Amazon Bedrock via the Converse API, wrapped by neatlogs so every call is traced."""

import os

import boto3
import neatlogs
from botocore.config import Config

DEFAULT_MODEL = "us.anthropic.claude-opus-5"


class LLMConfigError(RuntimeError):
    pass


class BedrockLLM:
    def __init__(self, model: str | None = None):
        profile = os.environ.get("UPSHIFT_AWS_PROFILE")
        if not profile:
            # Explicit on purpose: never bill whatever account the default AWS profile points at.
            raise LLMConfigError(
                "Set UPSHIFT_AWS_PROFILE to the AWS profile that should pay for Bedrock calls."
            )
        session = boto3.Session(profile_name=profile)
        client = session.client(
            "bedrock-runtime",
            region_name=os.environ.get("UPSHIFT_AWS_REGION", "us-west-2"),
            config=Config(retries={"max_attempts": 8, "mode": "adaptive"}, read_timeout=600),
        )
        self.client = neatlogs.wrap(client)
        self.model = model or os.environ.get("UPSHIFT_MODEL", DEFAULT_MODEL)
        self.input_tokens = 0
        self.output_tokens = 0

    def converse(self, system: str, messages: list[dict], tools: list[dict] | None = None,
                 max_tokens: int = 8000) -> dict:
        kwargs = {
            "modelId": self.model,
            "system": [{"text": system}],
            "messages": messages,
            "inferenceConfig": {"maxTokens": max_tokens},
        }
        if tools:
            kwargs["toolConfig"] = {"tools": [{"toolSpec": t} for t in tools]}
        response = self.client.converse(**kwargs)
        usage = response.get("usage", {})
        self.input_tokens += usage.get("inputTokens", 0)
        self.output_tokens += usage.get("outputTokens", 0)
        return response


def tool_spec(name: str, description: str, properties: dict, required: list[str]) -> dict:
    return {
        "name": name,
        "description": description,
        "inputSchema": {"json": {"type": "object", "properties": properties, "required": required}},
    }


def text_of(message: dict) -> str:
    return "\n".join(block["text"] for block in message.get("content", []) if "text" in block)


def tool_uses(message: dict) -> list[dict]:
    return [block["toolUse"] for block in message.get("content", []) if "toolUse" in block]


def tool_result(tool_use_id: str, text: str, error: bool = False) -> dict:
    return {"toolResult": {"toolUseId": tool_use_id, "content": [{"text": text}],
                           "status": "error" if error else "success"}}

"""Thin wrappers over the `entire graph` CLI: the agent's code-intelligence layer."""

import shutil
import subprocess

import neatlogs

TIMEOUT = 600


def available() -> bool:
    return shutil.which("entire") is not None


def _run(args: list[str], repo: str, stdin: str | None = None, timeout: int = TIMEOUT) -> str:
    if not available():
        return "entire CLI not installed; graph tools unavailable."
    proc = subprocess.run(
        ["entire", "graph", *args, "--repo", repo],
        input=stdin, capture_output=True, text=True, timeout=timeout,
    )
    out = proc.stdout.strip()
    if proc.returncode != 0:
        out = f"{out}\n[exit {proc.returncode}] {proc.stderr.strip()[-2000:]}".strip()
    return out


@neatlogs.span(kind="TOOL", tool_name="graph_search")
def search(repo: str, query: str, top_k: int = 8) -> str:
    return _run(["search", "--query", query, "--top-k", str(top_k), "--format", "agent",
                 "--profile", "full", "--max-context-bytes", "16000"], repo)


@neatlogs.span(kind="TOOL", tool_name="graph_impact")
def impact(repo: str, symbol: str) -> str:
    return _run(["impact", "--symbol", symbol], repo)


@neatlogs.span(kind="TOOL", tool_name="graph_explain")
def explain(repo: str, failure_text: str) -> str:
    return _run(["explain"], repo, stdin=failure_text)


@neatlogs.span(kind="GUARDRAIL", tool_name="graph_verify")
def verify(repo: str, test_cmd: str, record_baseline: str | None = None,
           pre_edit_baseline: str | None = None) -> str:
    args = ["verify", "--test", test_cmd, "--max-bytes", "4000"]
    if record_baseline:
        args += ["--record-baseline", record_baseline]
    if pre_edit_baseline:
        args += ["--pre-edit-baseline", pre_edit_baseline]
    return _run(args, repo, timeout=1800)

